export const PERIODS=['0','1','2','3','4','N','5','6','7','8','9','A','B','C','D'];
export const TIMES={0:['07:00','07:50'],1:['08:00','08:50'],2:['09:00','09:50'],3:['10:10','11:00'],4:['11:10','12:00'],N:['12:10','13:00'],5:['13:10','14:00'],6:['14:10','15:00'],7:['15:20','16:10'],8:['16:20','17:10'],9:['17:20','18:10'],A:['18:20','19:10'],B:['19:15','20:05'],C:['20:10','21:00'],D:['21:05','21:55']};
export const DAYS=['','一','二','三','四','五','六','日'];
export const DEMO=['F7-005','F7-007','F7-009','F7-012','F7-031','A9-402'];
export function courseSessions(course,tutorials={}){const group=course.tutorials?.[tutorials[course.id]];return [...course.sessions,...(group?.sessions??[]).map(s=>({...s,tutorial:true}))];}
export function conflicts(courses,tutorials={}){const found=[];for(let i=0;i<courses.length;i++)for(let j=i+1;j<courses.length;j++){const a=courses[i],b=courses[j];const matches=[];for(const s of courseSessions(a,tutorials))for(const t of courseSessions(b,tutorials))if(s.day&&s.day===t.day&&s.periods.some(p=>t.periods.includes(p)))matches.push(s.day);if(matches.length)found.push({a:a.id,b:b.id,days:[...new Set(matches)]});}return found;}
export function timeLabel(s){if(!s.periods?.length||!s.day)return '時間待公告';return `週${DAYS[s.day]} ${TIMES[s.periods[0]][0]}–${TIMES[s.periods.at(-1)][1]}`;}
export function googleUrl(room){if(!Number.isFinite(room?.lat)||!Number.isFinite(room?.lng))return null;return `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(room.lat+','+room.lng)}&travelmode=walking`;}
export function safeUrl(url,hosts){try{const u=new URL(url);return u.protocol==='https:'&&hosts.includes(u.hostname)?u.href:null;}catch{return null;}}
export function activeEntries(courses,tutorials,day){return courses.flatMap(c=>courseSessions(c,tutorials).filter(s=>s.day===day&&s.periods.length).map(s=>({course:c,session:s}))).sort((a,b)=>PERIODS.indexOf(a.session.periods[0])-PERIODS.indexOf(b.session.periods[0]));}
export function layoutEntries(entries){let group=[],end=-1;const output=[];function flush(){const lanes=[];for(const e of group){let lane=lanes.findIndex(n=>n<e.start);if(lane<0)lane=lanes.length;lanes[lane]=e.end;e.lane=lane;}for(const e of group)output.push({...e,laneCount:lanes.length});group=[];}for(const entry of entries){const start=PERIODS.indexOf(entry.session.periods[0]),finish=PERIODS.indexOf(entry.session.periods.at(-1));if(group.length&&start>end)flush();group.push({...entry,start,end:finish});end=group.length===1?finish:Math.max(end,finish);}flush();return output;}
export function taipeiNow(){const pieces=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(p=>[p.type,p.value]));return {day:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(pieces.weekday)||7,minute:Number(pieces.hour)*60+Number(pieces.minute)};}
export function nextClass(courses,tutorials,now=taipeiNow()){const entries=courses.flatMap(course=>courseSessions(course,tutorials).filter(s=>s.day&&s.periods.length).map(session=>{const [h,m]=TIMES[session.periods[0]][0].split(':').map(Number);let delta=(session.day-now.day)*1440+h*60+m-now.minute;if(delta<0)delta+=7*1440;return{course,session,delta};}));return entries.sort((a,b)=>a.delta-b.delta)[0]??null;}
